def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = 0
    for _, op in history:
        if op == 'D':
            opp_d += 1

    last_my, last_opp = history[-1]

    if n >= 99:
        return 'D'

    recent5 = history[-5:]
    recent3 = history[-3:]

    recent5_opp_d = sum(1 for _, op in recent5 if op == 'D')
    recent3_my_d = sum(1 for me, _ in recent3 if me == 'D')

    opp_streak = 0
    for _, op in reversed(history):
        if op == 'D':
            opp_streak += 1
        else:
            break

    my_streak = 0
    for me, _ in reversed(history):
        if me == 'D':
            my_streak += 1
        else:
            break

    # If the opponent has never defected, establish cooperation briefly,
    # then exploit an apparently unconditional cooperator with a short
    # verification round. If they ever defect, stop immediately and fall
    # into a robust conciliatory response.
    if opp_d == 0:
        if n < 8:
            return 'C'
        if n == 9:
            return 'C'
        return 'D'

    # Mostly-defect opponents: punish strongly, with rare probes for change.
    if recent5_opp_d >= 5 or opp_streak >= 5 or opp_d * 10 > n * 6:
        if opp_streak >= 4 or recent5_opp_d >= 4 or opp_d * 10 > n * 7:
            return 'D'
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Low-defect/conflict phase: after our own defection, appease briefly
    # so an isolated retaliatory cycle can return to mutual cooperation.
    if opp_d * 10 <= n * 3:
        if last_opp == 'D':
            # If we have not recently defected, their D is likely initiation
            # or continued exploitation; punish once.
            if opp_streak >= 3 or recent3_my_d == 0:
                return 'D'
            # Otherwise we are probably in a short punishment loop; restore cooperation.
            if my_streak >= 3:
                return 'C'
            return 'C'
        return 'C'

    # Mixed opponents: tit-for-tat-like, but avoid long mutual-defection traps.
    if last_opp == 'D':
        if recent3_my_d == 0:
            return 'D'

        if opp_streak >= 4:
            return 'D'

        # If we have been defecting too long while they are still mostly cooperative,
        # try to break the spiral.
        if my_streak >= 3 and opp_d * 10 <= n * 5:
            return 'C'

        if opp_d * 10 > n * 4:
            if rng.random() < 0.35:
                return 'C'
            return 'D'

        if rng.random() < 0.30:
            return 'C'
        return 'D'

    return 'C'
